const COOKIE = "id-token=";
function fromCookie() {
  const all = document.cookie ? document.cookie.split(";").map((s) => s.trim()) : [];
  const hit = all.find((c) => c.indexOf(COOKIE) === 0);
  if (!hit) return { error: "no id-token cookie" };
  let token = hit.slice(COOKIE.length);
  try { token = decodeURIComponent(token); } catch (e) {}
  const part = token.split(".")[1] || "";
  if (!part) return { error: "id-token is not a JWT" };
  const padded = part.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((part.length + 3) % 4);
  let claims = null;
  try { claims = JSON.parse(atob(padded)); } catch (e) { return { error: "id-token payload: " + (e && e.message ? e.message : e) }; }
  if (!claims || !claims.email) return { error: "id-token has no email claim" };
  return {
    found: true,
    source: "id-token cookie",
    email: claims.email,
    firstName: claims.given_name || "",
    lastName: claims.family_name || "",
    phone: claims.phone_number || "",
    emailVerified: !!claims.email_verified_at,
    phoneVerified: !!claims.phone_number_verified_at,
    expiresAt: claims.exp ? claims.exp * 1000 : 0
  };
}
const deadline = Date.now() + 10000;
let result = fromCookie();
while (!result.found && Date.now() < deadline) {
  await new Promise((r) => setTimeout(r, 1000));
  result = fromCookie();
}
if (result.found) return result;
try {
  const res = await fetch("https://identity.ticketmaster.com/json/user?hard=false&doNotTrack=false", {
    credentials: "include",
    headers: { accept: "application/json" }
  });
  if (res.ok) {
    const u = await res.json();
    if (u && u.emailAddress) {
      return {
        found: true,
        source: "identity user endpoint",
        email: u.emailAddress,
        firstName: u.firstName || "",
        lastName: u.lastName || "",
        phone: u.phoneNumber || "",
        emailVerified: !!u.emailVerifiedAt,
        phoneVerified: !!u.phoneNumberVerifiedAt,
        expiresAt: 0
      };
    }
    return { found: false, error: "identity endpoint returned no email" };
  }
  return { found: false, error: (result.error || "") + "; identity HTTP " + res.status + " at " + location.href };
} catch (e) {
  return { found: false, error: (result.error || "") + "; identity fetch: " + (e && e.message ? e.message : e) + " at " + location.href };
}
